def paginated_content():
 result=[]
 limits={'Таблица 1 —':[10,6],'Таблица 17 —':[8,8],'Таблица 19 —':[10,24,12]}
 for item in content:
  if item[0]!='table':result.append(item);continue
  _,title,heads,rows,widths=item
  chunks=next((v for k,v in limits.items() if title.startswith(k)),None)
  if not chunks:result.append(item);continue
  offset=0;number=re.search(r'Таблица (\d+)',title).group(1)
  for i,count in enumerate(chunks):
   if i:result.append(('break',))
   result.append(('table',title if i==0 else 'Продолжение таблицы '+number,heads,rows[offset:offset+count],widths));offset+=count
  assert offset==len(rows)
 return result

# Построение Word: A4, поля 30/15/20/20 мм, TNR 14, полуторный интервал.
def build():
 d=Document();sec=d.sections[0];sec.page_width=Mm(210);sec.page_height=Mm(297);sec.top_margin=Mm(20);sec.bottom_margin=Mm(20);sec.left_margin=Mm(30);sec.right_margin=Mm(15);sec.footer_distance=Mm(10);sec.different_first_page_header_footer=True
 for name in ['Normal','Title','Heading 1','Heading 2','Heading 3']:
  style=d.styles[name];style.font.name='Times New Roman';style.font.size=Pt(14);style.font.color.rgb=RGBColor(0,0,0);style.paragraph_format.line_spacing=1.5
  style.paragraph_format.space_after=Pt(0);style.paragraph_format.space_before=Pt(0)
 normal=d.styles['Normal'];normal.paragraph_format.first_line_indent=Mm(12.5);normal.paragraph_format.alignment=WD_ALIGN_PARAGRAPH.JUSTIFY
 for name in ['Heading 1','Heading 2','Heading 3']:
  s=d.styles[name];s.font.bold=True;s.paragraph_format.keep_with_next=True;s.paragraph_format.first_line_indent=Mm(12.5);s.paragraph_format.space_before=Pt(12);s.paragraph_format.space_after=Pt(8)
 d.styles['Heading 1'].paragraph_format.page_break_before=True
